package main

import (
	"fmt"
	"math"
)

func main() {
	// Integer
	var i int = 42
	var i64 int64 = 9_000_000_000
	fmt.Printf("int: %d, int64: %d\n", i, i64)
	fmt.Printf("MaxInt64: %d\n", math.MaxInt64)

	// Float
	var f64 float64 = 3.14159265358979
	fmt.Printf("float64: %.10f\n", f64)

	// Boolean
	bool1, bool2 := true, false
	fmt.Printf("AND: %t, OR: %t\n", bool1 && bool2, bool1 || bool2)

	// String
	s := "Hello, Gopher!"
	fmt.Printf("string: %s, len: %d\n", s, len(s))

	// Rune dan byte
	var r rune = '\u4e16' // karakter Cina: 世
	fmt.Printf("rune: %c (U+%04X)\n", r, r)
}
